export function hospitalsOf(city, keyword='') {
  const k = keyword.trim()
  return HOSPITALS.filter(h => h.city === city && (!k || h.name.includes(k)))
}

export function hospitalById(id) { return HOSPITALS.find(h => h.id === id) || null }

export function hospitalsByProvince(p) { return HOSPITALS.filter(h => h.province === p) }
